import React from 'react'
import classes from './ChapteServices.module.scss';

const ChapteServices = () => {
    return (
        <section className={classes.services}> {/* Используем стили */}
          <h2 className={classes.title}>Услуги</h2> {/* Используем стили */}
          <img className={classes.image} src="/img/Services.png" alt="Services" /> {/* Замените путь на ваш */}
          <div className={classes.items}>
            {servicesData.map((service) => (
              <ServiceItem
                key={service.id} // Уникальный ключ для каждого элемента
                title={service.title}
                description={service.description}
              />
            ))}
            <button className={classes.button}>Смотреть все услуги</button> {/* Используем стили */}
          </div>
        </section>
      );
}

export default ChapteServices
